package me.alpha432.oyvey.manager;

import java.io.File;
import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Comparator;
import java.util.List;
import me.alpha432.oyvey.OyVey;
import me.alpha432.oyvey.event.Stage;
import me.alpha432.oyvey.event.impl.entity.DeathEvent;
import me.alpha432.oyvey.event.impl.entity.player.TickEvent;
import me.alpha432.oyvey.event.impl.entity.player.UpdateWalkingPlayerEvent;
import me.alpha432.oyvey.event.impl.input.KeyInputEvent;
import me.alpha432.oyvey.event.impl.network.PacketEvent;
import me.alpha432.oyvey.event.system.Subscribe;
import me.alpha432.oyvey.features.Feature;
import me.alpha432.oyvey.features.script.LuaScript;
import net.fabricmc.loader.api.FabricLoader;

public class ScriptManager extends Feature {
   private final List<LuaScript> scripts = new ArrayList<>();
   private final Path scriptsDir = FabricLoader.getInstance().getGameDir().resolve("oyvey").resolve("scripts");

   public void init() {
      try {
         Files.createDirectories(this.scriptsDir);
         this.writeDocumentation();
         this.loadAll();
      } catch (IOException var2) {
         OyVey.LOGGER.error("[ScriptManager] Init failed: {}", var2.getMessage());
      }

      EVENT_BUS.register(this);
   }

   private void loadAll() {
      File[] files = this.scriptsDir.toFile().listFiles((d, n) -> n.endsWith(".lua"));
      if (files != null) {
         Arrays.sort(files, Comparator.comparing(File::getName));

         for (File f : files) {
            LuaScript script = new LuaScript(f);
            script.load();
            this.scripts.add(script);
            OyVey.LOGGER.info("[ScriptManager] Loaded: {}", script.getName());
         }
      }
   }

   public void reload() {
      for (LuaScript s : this.scripts) {
         if (s.isEnabled()) {
            s.disable();
         }
      }

      this.scripts.clear();
      this.loadAll();
   }

   @Subscribe
   public void onTick(TickEvent event) {
      if (!nullCheck()) {
         for (LuaScript s : this.scripts) {
            s.onTick();
         }
      }
   }

   @Subscribe
   public void onMotion(UpdateWalkingPlayerEvent event) {
      if (!nullCheck()) {
         if (event.getStage() == Stage.MOTION_PRE) {
            for (LuaScript s : this.scripts) {
               s.onMotionPre();
            }
         } else if (event.getStage() == Stage.POST) {
            for (LuaScript s : this.scripts) {
               s.onMotionPost();
            }
         }
      }
   }

   @Subscribe
   public void onPacketSend(PacketEvent.Send event) {
      if (mc.player != null) {
         String type = event.getPacket().getClass().getSimpleName();

         for (LuaScript s : this.scripts) {
            s.onPacketSend(type);
         }
      }
   }

   @Subscribe
   public void onPacketReceive(PacketEvent.Receive event) {
      if (mc.player != null) {
         String type = event.getPacket().getClass().getSimpleName();

         for (LuaScript s : this.scripts) {
            s.onPacketReceive(type);
         }
      }
   }

   @Subscribe
   public void onKey(KeyInputEvent event) {
      for (LuaScript s : this.scripts) {
         s.onKey(event.getKey());
      }
   }

   @Subscribe
   public void onDeath(DeathEvent event) {
      if (mc.player != null && event.getEntity() == mc.player) {
         for (LuaScript s : this.scripts) {
            s.onDeath();
         }
      }
   }

   public List<LuaScript> getScripts() {
      return this.scripts;
   }

   public Path getScriptsDir() {
      return this.scriptsDir;
   }

   private void writeDocumentation() throws IOException {
      Path doc = this.scriptsDir.resolve("API_DOCUMENTATION.txt");
      if (!Files.exists(doc)) {
         Files.writeString(doc, buildDocString(), StandardCharsets.UTF_8);
         OyVey.LOGGER.info("[ScriptManager] Wrote API_DOCUMENTATION.txt");
      }
   }

   private static String buildDocString() {
      return "================================================================================\n                        SR CLIENT  \u2014  LUA SCRIPTING API\n                              Full Reference Guide\n================================================================================\n\nScripts are .lua files placed in:\n  <minecraft_directory>/oyvey/scripts/\n\nEach script is listed in the \"Scripts\" tab of every ClickGUI mode. Toggle a\nscript on or off just like a module. Your changes persist until the next reload.\n\nTo reload all scripts without restarting the game, right-click the \"Scripts\"\npanel header and choose \"Reload\", or use the reload button in the GUI.\n\n\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n BASIC FILE STRUCTURE\n\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n\nEvery script file can define the following at the top level:\n\n  NAME        = \"My Script\"          -- Display name in the GUI  (required)\n  DESCRIPTION = \"What it does\"      -- Short description         (optional)\n\nThen you define settings and event hooks:\n\n  -- Settings (called immediately when the script loads)\n  local speed = script.addSlider(\"Speed\", 1.0, 0.0, 5.0)\n  local active = script.addBoolean(\"Active\", true)\n  local mode   = script.addEnum(\"Mode\", {\"FAST\", \"SLOW\"}, 1)\n\n  -- Event hooks  (only define the ones you need)\n  function onEnable()   ... end\n  function onDisable()  ... end\n  function onTick()     ... end\n  ... (see full list below)\n\n\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n MINIMAL EXAMPLE \u2014 AutoSprint.lua\n\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n\n  NAME        = \"AutoSprint\"\n  DESCRIPTION = \"Always sprints when moving forward\"\n\n  function onTick()\n    if not player.isSneaking() and player.getFoodLevel() > 6 then\n      player.setSprinting(true)\n    end\n  end\n\n\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n EVENT HOOKS  (functions you define; only define the ones you need)\n\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n\n  function onEnable()\n    -- Called when the script is toggled ON in the GUI.\n    -- Use for setup: resetting variables, sending messages, etc.\n\n  function onDisable()\n    -- Called when the script is toggled OFF.\n    -- Use for cleanup: restore movement, clear rotations, etc.\n\n  function onTick()\n    -- Called every game tick (~20 times per second) while the player and\n    -- world are loaded.  Good for continuous logic.\n\n  function onMotionPre()\n    -- Called BEFORE the player's position packet is sent to the server.\n    -- Best place to modify player.setMotion() or rotation.setServer() so\n    -- the server sees the correct values in the next packet.\n\n  function onMotionPost()\n    -- Called AFTER the position packet has been sent.\n    -- Good for restoring rotations to their real values after spoofing.\n\n  function onPacketSend(packetType)\n    -- Called when ANY outgoing packet is about to be sent.\n    -- packetType : string \u2014 simple class name of the packet,\n    --              e.g. \"ServerboundMovePlayerPacket$Pos\",\n    --                   \"ServerboundUseItemPacket\"\n\n  function onPacketReceive(packetType)\n    -- Called when ANY incoming packet is received from the server.\n    -- packetType : string \u2014 simple class name, e.g.\n    --              \"ClientboundSetEntityMotionPacket\",\n    --              \"ClientboundPlayerPositionPacket\"\n\n  function onKey(keyCode)\n    -- Called when any key is pressed.\n    -- keyCode : integer \u2014 GLFW key constant (e.g. 32 = Space, 87 = W)\n    -- Use GLFW key code tables to identify specific keys.\n    -- Common codes:  32=Space  87=W  65=A  83=S  68=D  81=Q  69=E\n    --                340=LShift  341=LCtrl  256=Escape  257=Enter\n\n  function onDeath()\n    -- Called when the local player dies.\n\n\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n SCRIPT SETTINGS API  (script.*)\n\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n\nSettings let you expose configurable values in the GUI's settings panel.\nCall these at the TOP LEVEL of your script (outside any function) so they\nregister when the script loads.\n\n  script.addBoolean(name, default) -> handle\n    -- Creates a true/false toggle in the GUI.\n    -- name    : string  \u2014 label shown in the GUI\n    -- default : boolean \u2014 initial value (true or false)\n    -- Returns a handle table with:\n    --   handle.get()         -> boolean  (current value)\n    --   handle.set(boolean)  -> sets the value\n\n    Example:\n      local enabled = script.addBoolean(\"Sprint Always\", false)\n      function onTick()\n        if enabled.get() then player.setSprinting(true) end\n      end\n\n  script.addSlider(name, default, min, max) -> handle\n    -- Creates a draggable number slider in the GUI.\n    -- name    : string  \u2014 label shown in the GUI\n    -- default : number  \u2014 initial value\n    -- min     : number  \u2014 minimum allowed value\n    -- max     : number  \u2014 maximum allowed value\n    -- Returns a handle table with:\n    --   handle.get()        -> number   (current value)\n    --   handle.set(number)  -> sets the value (clamped to min/max)\n\n    Example:\n      local speed = script.addSlider(\"Fly Speed\", 0.3, 0.1, 2.0)\n      function onTick()\n        player.setMotion(0, speed.get(), 0)\n      end\n\n  script.addEnum(name, optionsTable, defaultIndex) -> handle\n    -- Creates a cycling enum button in the GUI.\n    -- name         : string  \u2014 label shown in the GUI\n    -- optionsTable : table   \u2014 list of string options  { \"A\", \"B\", \"C\" }\n    -- defaultIndex : integer \u2014 1-based index of the initial selection\n    -- Returns a handle table with:\n    --   handle.get()   -> string  (current option name)\n    --   handle.set(s)  -> sets by string value\n    --   handle.cycle() -> moves to the next option (wraps around)\n\n    Example:\n      local mode = script.addEnum(\"Mode\", {\"ATTACK\", \"DEFEND\", \"IDLE\"}, 1)\n      function onTick()\n        if mode.get() == \"ATTACK\" then\n          -- attack logic\n        end\n      end\n\n  script.getSetting(name) -> value\n    -- Reads a setting's current value by name string.\n    -- Useful if you lost the handle reference.\n\n  script.getName()        -> string   (script display name)\n  script.getDescription() -> string   (script description)\n  script.isEnabled()      -> boolean  (whether the script is currently on)\n\n\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n PLAYER API  (player.*)\n\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n\n--- POSITION & MOVEMENT ---\n\n  player.getX()  -> number   Player X coordinate\n  player.getY()  -> number   Player Y coordinate (feet level)\n  player.getZ()  -> number   Player Z coordinate\n\n  player.getMotionX() -> number   Current X velocity (blocks per tick)\n  player.getMotionY() -> number   Current Y velocity\n  player.getMotionZ() -> number   Current Z velocity\n\n  player.setMotion(x, y, z)\n    -- Directly sets the player's velocity (blocks per tick).\n    -- Call this in onMotionPre() so the server packet reflects it.\n    -- Example: player.setMotion(0, 0.42, 0)  -- jump impulse\n\n  player.jump()\n    -- Applies a 0.42 Y velocity (standard Minecraft jump force).\n\n--- ROTATION ---\n\n  player.getYaw()   -> number   Horizontal look angle in degrees (\u2212180 to 180)\n  player.getPitch() -> number   Vertical look angle in degrees   (\u221290 to 90)\n\n  (To set server-side rotation silently, use rotation.setServer() instead.)\n\n--- STATUS ---\n\n  player.getHealth()    -> number   Current health (0.0 \u2013 maxHealth)\n  player.getMaxHealth() -> number   Maximum health (usually 20.0)\n  player.getFoodLevel() -> integer  Food level (0 \u2013 20)\n\n  player.isOnGround()   -> boolean  True if standing on a block\n  player.isSprinting()  -> boolean\n  player.setSprinting(bool)\n  player.isSneaking()   -> boolean\n  player.isFlying()     -> boolean  Creative/ability flying\n  player.setFlying(bool)\n\n--- INVENTORY ---\n\n  player.getSelectedSlot()     -> integer  Hotbar slot 0\u20138\n  player.setSelectedSlot(slot)            Sets the held slot (0\u20138)\n  player.getHeldItemName()     -> string   Registry name of held item\n                                           e.g. \"minecraft:diamond_sword\"\n  player.getInventoryItem(slot) -> string  Item name at inventory slot\n                                           (0\u20138 = hotbar, 9\u201335 = main inv,\n                                            36\u201339 = armor, 40 = offhand)\n\n--- ACTIONS ---\n\n  player.swing()\n    -- Swings the main hand (visual + triggers hit detection like a click).\n\n  player.attack(entityId)\n    -- Attacks an entity by its integer entity ID.\n    -- Get IDs from world.getEntities() or world.getClosestPlayer().id\n    -- Example:\n    --   local target = world.getClosestPlayer()\n    --   if target then player.attack(target.id) end\n\n  player.sendChat(message)\n    -- Sends a real chat message (visible to other players).\n    -- Do NOT prefix with \"/\" to avoid command conflicts.\n\n  player.printChat(message)\n    -- Shows a client-side chat message (only visible to you).\n    -- Supports Minecraft color codes: \u00a7a = green, \u00a7c = red, \u00a7e = yellow, etc.\n    -- Example: player.printChat(\"\u00a7aScript enabled!\")\n\n--- INFO ---\n\n  player.getName() -> string   Your in-game username\n\n\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n WORLD API  (world.*)\n\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n\n--- BLOCKS ---\n\n  world.getBlock(x, y, z) -> string\n    -- Returns the full registry name of the block at the given block position.\n    -- Example: \"minecraft:stone\", \"minecraft:air\", \"minecraft:obsidian\"\n    -- Coordinates are integers (block positions, not exact coordinates).\n\n  world.isAir(x, y, z)   -> boolean   True if the block is empty air\n  world.isSolid(x, y, z) -> boolean   True if the block is solid (has collision)\n\n  Example (check block below player):\n    local bx = util.floor(player.getX())\n    local by = util.floor(player.getY()) - 1\n    local bz = util.floor(player.getZ())\n    if world.isSolid(bx, by, bz) then\n      -- standing on something\n    end\n\n--- TIME & DIMENSION ---\n\n  world.getTime()    -> integer   World time in ticks (mod 24000 for day cycle)\n  world.isDay()      -> boolean   True between tick 0 and 13000\n  world.getDimension() -> string  Dimension key, e.g. \"minecraft:overworld\",\n                                  \"minecraft:the_nether\", \"minecraft:the_end\"\n\n--- ENTITIES ---\n\n  world.getPlayers() -> table\n    -- Returns a list of all OTHER players in render distance.\n    -- Each entry is a table with fields:\n    --   .name   string   Display name\n    --   .x      number   X position\n    --   .y      number   Y position\n    --   .z      number   Z position\n    --   .health number   Current HP\n    --   .id     integer  Entity ID (used by player.attack())\n    -- Example:\n    --   for i, p in ipairs(world.getPlayers()) do\n    --     player.printChat(p.name .. \" HP: \" .. p.health)\n    --   end\n\n  world.getClosestPlayer() -> table or nil\n    -- Returns the nearest OTHER player's info table (same fields as above,\n    -- plus .dist = distance in blocks), or nil if no players are nearby.\n\n  world.getEntities() -> table\n    -- Returns ALL entities in the world (mobs, items, projectiles, etc.).\n    -- Each entry has:\n    --   .name   string   Entity display name or type\n    --   .type   string   Short type string (e.g. \"zombie\", \"arrow\")\n    --   .x / .y / .z  number\n    --   .health number   0 for non-living entities (items, projectiles)\n    --   .id     integer  Entity ID\n\n\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n ROTATION API  (rotation.*)\n\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n\nThe rotation API controls the SERVER-SIDE rotation \u2014 the yaw/pitch values that\nare included in position packets. Your camera does NOT snap visually.\n\n  rotation.setServer(yaw, pitch)\n    -- Set the server-visible rotation.\n    -- Call this in onMotionPre() to apply before the packet is sent.\n    -- yaw   : -180 to 180  (horizontal, 0=south, 90=west, -90=east, 180=north)\n    -- pitch : -90 to 90    (vertical,   -90=up, 0=level, 90=down)\n\n  rotation.clear()\n    -- Removes the server-side rotation override.\n    -- The next position packet will use the real camera rotation.\n\n  rotation.getServerYaw()   -> number   Currently set server yaw\n  rotation.getServerPitch() -> number   Currently set server pitch\n\n  rotation.lookAt(x, y, z)\n    -- Computes and sets the server rotation to look at world coordinates.\n    -- Automatically calculates yaw and pitch to face the given point.\n    -- Example (aim at the closest player):\n    --   function onMotionPre()\n    --     local target = world.getClosestPlayer()\n    --     if target then\n    --       rotation.lookAt(target.x, target.y + 1.6, target.z)\n    --     end\n    --   end\n\n\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n MODULE API  (module.*)\n\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n\n  module.isEnabled(name) -> boolean\n    -- Returns true if the module with that name is currently enabled.\n    -- Names are case-sensitive and match what's shown in the GUI.\n\n  module.enable(name)    -- Enables a module (does nothing if already on)\n  module.disable(name)   -- Disables a module (does nothing if already off)\n  module.toggle(name)    -- Toggles a module on or off\n\n  Common module names you can interact with:\n    \"Sprint\", \"Fly\", \"Velocity\", \"KillauraRecode\", \"BedNuker\",\n    \"PlayerESP\", \"Scaffold\", \"AutoGapple\", \"AutoEat\", \"Speed\", ...\n\n  Example \u2014 emergency disable Fly when health is low:\n    function onTick()\n      if player.getHealth() < 6 and module.isEnabled(\"Fly\") then\n        module.disable(\"Fly\")\n        player.printChat(\"\u00a7cDisabled Fly \u2014 low health!\")\n      end\n    end\n\n\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n UTIL API  (util.*)\n\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n\n  util.log(message)\n    -- Prints a message to the game log / console.\n    -- Useful for debugging. Output appears in logs/latest.log.\n\n  util.time() -> integer\n    -- Returns the current system time in milliseconds (System.currentTimeMillis).\n    -- Useful for timing: local lastTick = 0\n    --                    if util.time() - lastTick > 500 then ... end\n\n  util.random(min, max) -> number\n    -- Random float between min and max.\n    -- Example: local jitter = util.random(-0.5, 0.5)\n\n  util.distance(x1, y1, z1, x2, y2, z2) -> number\n    -- 3D Euclidean distance between two points.\n\n  util.calcAngle(fromX, fromY, fromZ, toX, toY, toZ) -> table\n    -- Returns { yaw = ..., pitch = ... } to look from \"from\" to \"to\".\n    -- This is the same calculation the internal aimbot uses.\n\n  util.clamp(value, min, max) -> number   Clamps value to [min, max]\n  util.floor(n)  -> integer               Floor\n  util.ceil(n)   -> integer               Ceiling\n  util.round(n)  -> integer               Nearest integer\n\n\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n ADVANCED EXAMPLES\n\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n\n--- Example 1: KillScript \u2014 auto-attack closest player ---\n\n  NAME        = \"KillScript\"\n  DESCRIPTION = \"Attacks the closest player every tick\"\n\n  local range = script.addSlider(\"Range\", 4.0, 1.0, 10.0)\n\n  function onTick()\n    local target = world.getClosestPlayer()\n    if target == nil then return end\n    if target.dist > range.get() then return end\n\n    rotation.lookAt(target.x, target.y + 1.6, target.z)\n    player.attack(target.id)\n    player.swing()\n  end\n\n  function onDisable()\n    rotation.clear()\n  end\n\n\n--- Example 2: BunnyHop \u2014 jump every time you land ---\n\n  NAME        = \"BunnyHop\"\n  DESCRIPTION = \"Automatically jumps on landing to maintain speed\"\n\n  local wasOnGround = false\n\n  function onMotionPre()\n    local onGround = player.isOnGround()\n    if onGround and not wasOnGround then\n      player.jump()\n    end\n    wasOnGround = onGround\n  end\n\n\n--- Example 3: AutoDisableOnDamage \u2014 disable Fly when teleported back ---\n\n  NAME        = \"AntiSetback\"\n  DESCRIPTION = \"Disables Fly when server sends a position correction\"\n\n  function onPacketReceive(type)\n    if type == \"ClientboundPlayerPositionPacket\" then\n      module.disable(\"Fly\")\n      player.printChat(\"\u00a7eSetback received \u2014 Fly disabled.\")\n    end\n  end\n\n\n--- Example 4: TimedAction \u2014 do something every 500ms ---\n\n  NAME = \"TimedSprintReset\"\n\n  local lastReset = 0\n\n  function onTick()\n    if util.time() - lastReset > 500 then\n      player.setSprinting(false)\n      player.setSprinting(true)\n      lastReset = util.time()\n    end\n  end\n\n\n--- Example 5: InventoryHelper \u2014 auto-equip best armor slot ---\n\n  NAME        = \"ArmorCheck\"\n  DESCRIPTION = \"Prints armor slot contents on enable\"\n\n  function onEnable()\n    for slot = 36, 39 do\n      local item = player.getInventoryItem(slot)\n      player.printChat(\"Slot \" .. slot .. \": \" .. item)\n    end\n  end\n\n\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n TIPS & GOTCHAS\n\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n\n1. All API calls are SYNCHRONOUS on the Minecraft main thread.\n   Do NOT call blocking operations (file I/O, network) inside event hooks \u2014\n   this will freeze the game.\n\n2. player.setMotion() should be called in onMotionPre(), not onTick().\n   onTick() runs after physics; onMotionPre() runs before the packet goes out,\n   so the server sees your intended velocity.\n\n3. rotation.setServer() should also be called in onMotionPre().\n   Call rotation.clear() in onMotionPost() or onDisable() to restore.\n\n4. world.getEntities() and world.getPlayers() include ONLY entities within\n   the client's render distance \u2014 you cannot see entities beyond that.\n\n5. Script settings (addBoolean, addSlider, addEnum) are LOCAL \u2014 they reset\n   to defaults every time the script file is reloaded. If you need persistent\n   settings, write your own save/load logic using Lua's io library.\n\n6. util.log() writes to the Minecraft log file (logs/latest.log). Use this\n   for debugging instead of player.printChat() so chat stays clean.\n\n7. LuaJ implements Lua 5.2. Standard Lua libraries are available:\n   string, table, math, io, os, coroutine.\n   io and os give file/system access \u2014 use responsibly.\n\n8. If a script throws an error, it is logged but execution continues.\n   The script will NOT automatically disable \u2014 errors in onTick() will be\n   logged every tick until you fix and reload the script.\n\n9. Scripts are reloaded by clicking the Reload button in the Scripts panel\n   or by restarting the game. Changes to .lua files take effect on reload.\n\n10. The NAME and DESCRIPTION fields must be plain strings at the top level,\n    not inside any function. They are read right after the file executes.\n\n================================================================================\n";
   }
}
